/**
 * A lente perfeita — os raios que só encontram um ponto na curvatura certa.
 *
 * O olho não enxerga porque tem uma lente: enxerga porque a lente tem a
 * curvatura CERTA. Achatada demais, os raios cruzam atrás da retina e a imagem
 * chega borrada; curva demais, cruzam antes e borra de novo. A cena mostra os
 * raios de verdade — traçados, não sugeridos — e a mancha que eles formam na
 * retina, que encolhe até virar um ponto.
 *
 * A refração é uma aproximação de lente fina: o raio que entra à altura h sai
 * apontando para o foco, e o foco é o que a curvatura dita. Basta para a lição,
 * e é o que deixa a cena continuar honesta nos extremos do slider.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const RAIOS = 7;

const lente: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const curvatura = limitar(numeroDe(valores, 'c', 0), 0, 100);
    const ok = info.ok === true;
    const tinta = ok ? cor.verde : cor.azul;

    titulo(ctx, L, A, 'Um foco só, exatamente na retina');

    const xLente = L * 0.34;
    const xRetina = L * 0.88;
    const eixo = A * 0.52;
    const meiaAltura = A * 0.24;

    // ── O eixo óptico ─────────────────────────────────────────────────────
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(L * 0.04, eixo);
    ctx.lineTo(xRetina, eixo);
    ctx.stroke();
    ctx.setLineDash([]);

    // ── A distância focal ─────────────────────────────────────────────────
    // Curvatura 50% põe o foco exatamente na retina; 0% manda para o infinito.
    const distanciaRetina = xRetina - xLente;
    const foco = curvatura <= 0.5 ? Number.POSITIVE_INFINITY : distanciaRetina * (50 / curvatura);
    const xFoco = xLente + foco;

    // ── A lente ───────────────────────────────────────────────────────────
    const bojo = (L * 0.055 * curvatura) / 100 + 2;
    ctx.beginPath();
    ctx.moveTo(xLente, eixo - meiaAltura);
    ctx.quadraticCurveTo(xLente + bojo * 2, eixo, xLente, eixo + meiaAltura);
    ctx.quadraticCurveTo(xLente - bojo * 2, eixo, xLente, eixo - meiaAltura);
    ctx.closePath();
    ctx.fillStyle = 'rgb(120 190 235 / 35%)';
    ctx.fill();
    ctx.strokeStyle = tinta;
    ctx.lineWidth = 2.2;
    ctx.stroke();

    // ── Os raios ──────────────────────────────────────────────────────────
    // Onde cada raio cruza a retina: é a largura desta nuvem que vira a mancha.
    let maisAlto = 0;

    for (let i = 0; i < RAIOS; i++) {
      const h = (i / (RAIOS - 1) - 0.5) * 2 * meiaAltura * 0.86;
      const y = eixo + h;

      ctx.strokeStyle = tinta;
      ctx.lineWidth = 1.6;
      ctx.globalAlpha = 0.85;
      ctx.beginPath();
      ctx.moveTo(L * 0.04, y);
      ctx.lineTo(xLente, y);

      // Depois da lente o raio segue para o foco; sem curvatura, segue reto.
      const yNaRetina = Number.isFinite(foco)
        ? y + (h === 0 ? 0 : -h * (distanciaRetina / foco))
        : y;
      ctx.lineTo(xRetina, yNaRetina);
      ctx.stroke();

      maisAlto = Math.max(maisAlto, Math.abs(yNaRetina - eixo));
    }
    ctx.globalAlpha = 1;

    // O ponto onde os raios se cruzam de fato, quando ele cabe na cena.
    if (Number.isFinite(foco) && xFoco > xLente && xFoco < L * 0.98) {
      ctx.fillStyle = cor.ouro;
      ctx.beginPath();
      ctx.arc(xFoco, eixo, 4.5, 0, Math.PI * 2);
      ctx.fill();
    }

    // ── A retina ──────────────────────────────────────────────────────────
    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(xRetina, eixo - meiaAltura * 1.1);
    ctx.quadraticCurveTo(xRetina + L * 0.05, eixo, xRetina, eixo + meiaAltura * 1.1);
    ctx.stroke();

    // A mancha: o que a retina de fato recebe.
    const miudo = limitar(A * 0.032, 8, 11);
    ctx.fillStyle = ok ? cor.verde : cor.erro;
    ctx.globalAlpha = 0.55;
    ctx.beginPath();
    ctx.ellipse(xRetina, eixo, 4, Math.max(3, maisAlto), 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;

    etiqueta(ctx, 'retina', xRetina, eixo + meiaAltura * 1.28, miudo, cor.texto, 700);
    etiqueta(ctx, 'lente', xLente, eixo - meiaAltura * 1.25, miudo, tinta, 700);

    texto(ctx, `curvatura ${Math.round(curvatura)}%`, L / 2, A * 0.88, miudo * 1.15, {
      cor: tinta,
      peso: 800,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Os raios convergem num único foco, na retina ✔',
      curvatura < 50
        ? 'Lente achatada: os raios cruzariam atrás da retina.'
        : 'Lente curva demais: os raios cruzam antes de chegar.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default lente;
